public static bool IsValidNumber(string? number)
{
    if (number is null || number.Length != 10 || !number.All(char.IsAsciiDigit))
        return false;

    var sum = 0;
    for (var i = 0; i < 10; i++)
    {
        var digit = number[9 - i] - '0';
        if (i % 2 == 1)
        {
            digit *= 2;
            if (digit > 9) digit -= 9;
        }
        sum += digit;
    }
    return sum % 10 == 0;
}

